const int pinBoton = 2;
const int pinLedVerde = 12;
const int pinLedRojo = 13;

void setup() {
  pinMode(pinBoton, INPUT); // Configura el botón como entrada
  pinMode(pinLedVerde, OUTPUT);
  pinMode(pinLedRojo, OUTPUT);
}

void loop() {
  int estadoBoton = digitalRead(pinBoton); // Lee el estado del botón

  if (estadoBoton == HIGH) {
    // Si el botón está presionado (5V)
    digitalWrite(pinLedVerde, HIGH);
    digitalWrite(pinLedRojo, LOW);
  } else {
    // Si el botón NO está presionado (0V)
    digitalWrite(pinLedVerde, LOW);
    digitalWrite(pinLedRojo, HIGH);
  }
}

// Secuencia estilo 'Auto Fantástico' usando un bucle for
void setup() {
  // Configura los pines del 2 al 6 como salidas
  for (int pin = 2; pin <= 6; pin++) {
    pinMode(pin, OUTPUT);
  }
}

void loop() {
  // Enciende y apaga secuencialmente del pin 2 al 6
  for (int pin = 2; pin <= 6; pin++) {
    digitalWrite(pin, HIGH);
    delay(100);
    digitalWrite(pin, LOW);
  }
}

const int pinLDR = A0;
const int pinLedAlarma = 13;

void setup() {
  pinMode(pinLedAlarma, OUTPUT);
  Serial.begin(9600); // Inicia el monitor serie
}

void loop() {
  int valorLuz = analogRead(pinLDR); // Lee el voltaje del sensor

  Serial.print("Valor de luz: ");
  Serial.println(valorLuz);

  // Si hay oscuridad (valor bajo)
  if (valorLuz < 300) {
    digitalWrite(pinLedAlarma, HIGH); // Enciende la luz de emergencia
  } else {
    digitalWrite(pinLedAlarma, LOW);
  }

  delay(500);
}

const int pinAnalogo = A0;

void setup() {
  Serial.begin(9600); // Inicializa comunicación para mostrar resultados
}

void loop() {
  int valorADC = analogRead(pinAnalogo); // Lee de 0 a 1023

  // Convierte el valor digital de nuevo a voltios reales
  float voltaje = valorADC * (5.0 / 1023.0);

  Serial.print("Lectura ADC: ");
  Serial.print(valorADC);
  Serial.print(" | Voltaje Real: ");
  Serial.print(voltaje);
  Serial.println(" V");

  delay(300);
}

const int pinPotencimetro = A0;
const int pinLedPWM = 9; // Pin con soporte para PWM (~)

void setup() {
  pinMode(pinLedPWM, OUTPUT);
}

void loop() {
  int valorEntrada = analogRead(pinPotencimetro); // Lectura 0 a 1023

  // Escala de 0-1023 a 0-255 para el brillo del LED
  int brillo = map(valorEntrada, 0, 1023, 0, 255);

  analogWrite(pinLedPWM, brillo); // Modula la intensidad del LED
  delay(10);
}

const int pinTrig = 9;
const int pinEcho = 10;
const int pinBuzzer = 6;

void setup() {
  pinMode(pinTrig, OUTPUT);
  pinMode(pinEcho, INPUT);
  pinMode(pinBuzzer, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  // Genera un pulso limpio en el Trigger de 10 microsegundos
  digitalWrite(pinTrig, LOW);
  delayMicroseconds(2);
  digitalWrite(pinTrig, HIGH);
  delayMicroseconds(10);
  digitalWrite(pinTrig, LOW);

  // Mide el tiempo de retorno de la onda en el Echo
  long duracion = pulseIn(pinEcho, HIGH);

  // Calcula la distancia en centímetros
  int distancia = duracion / 58;

  Serial.print("Distancia detectada: ");
  Serial.print(distancia);
  Serial.println(" cm");

  // Alarma de proximidad: suena si un objeto está a menos de 15 cm
  if (distancia < 15 && distancia > 0) {
    digitalWrite(pinBuzzer, HIGH);
  } else {
    digitalWrite(pinBuzzer, LOW);
  }

  delay(200);
}

#include <Servo.h> // Incluye la librería obligatoria

Servo miServo; // Crea el objeto servo

void setup() {
  miServo.attach(9); // Vincula la señal al pin digital 9
}

void loop() {
  // Mueve suavemente el servomotor de 0 a 180 grados
  for (int angulo = 0; angulo <= 180; angulo += 10) {
    miServo.write(angulo);
    delay(50); // Pausa para dar tiempo al movimiento mecánico
  }

  // Regresa de 180 a 0 grados
  for (int angulo = 180; angulo >= 0; angulo -= 10) {
    miServo.write(angulo);
    delay(50);
  }
}

const int pinLed = 13;

void setup() {
  pinMode(pinLed, OUTPUT);
  Serial.begin(9600); // Configura el puerto a 9600 baudios
  Serial.println("=== SISTEMA INICIALIZADO ===");
  Serial.println("Escriba '1' para Encender o '0' para Apagar:");
}

void loop() {
  // Verifica si el usuario envió algún carácter desde la PC
  if (Serial.available() > 0) {
    char comando = Serial.read(); // Lee el carácter recibido

    if (comando == '1') {
      digitalWrite(pinLed, HIGH);
      Serial.println("-> Estado: LED ENCENDIDO");
    } else if (comando == '0') {
      digitalWrite(pinLed, LOW);
      Serial.println("-> Estado: LED APAGADO");
    }
  }
}
